import React, { PropsWithChildren } from "react";
import clsx from "clsx";
import {
  Align as AlignStyles,
  Justify as JustifyStyles,
  Row as RowStyles,
} from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { AlignItems, JustifyContent } from "../helperTypes";
import { CommonProps } from "../helperTypes";

type Props = PropsWithChildren<{
  /**
   * Defines the `justify-content` style property.
   */
  justify?: JustifyContent;
  /**
   * Defines the `align-items` style property.
   */
  alignItems?: AlignItems;
}>;

export type RowProps = Props & CommonProps;

const useStyles = createUseStyles(RowStyles, "row");
const useJustifyStyles = createUseStyles(JustifyStyles, "justify");
const useAlignStyles = createUseStyles(AlignStyles, "align");

const Row = (props: RowProps) => {
  const { alignItems, children, className, justify, ...rest } = props;
  const classes = useStyles();
  const alignClasses = useAlignStyles();
  const justifyClasses = useJustifyStyles();

  return (
    <div
      className={clsx(
        classes.root,
        className,
        justify && justifyClasses[`content-${justify}`],
        alignItems && alignClasses[`items-${alignItems}`]
      )}
      {...rest}
    >
      {children}
    </div>
  );
};

export default Row;
